/// The kinds of card, each with its actions in order; the first is its
/// filled one.
enum CardKind: String, CaseIterable, Sendable {
    /// An airport's (the owner, 2026-11-11: "fly here, add stop, call and address ... no need for other buttons", Favorite in Address's place since).
    case airport
    /// An airport's, opened while the pilot adds a stop (the one search asked for one): Add Stop first and filled, no Fly Here, Address last (the owner, 2026-11-18).
    case airportAsStop
    /// An airport's where Add Stop cannot be used (the field on the route already, closed): Address last in its place, not a greyed tile (the owner, 2026-11-20).
    case airportStopOff
    /// A point held on the map: the airspace card's.
    case point
    /// A VOR, a fix or a VFR waypoint.
    case navaid

    var actions: [CardAction] {
        switch self {
        case .airport: [.flyHere, .addStop, .call, .favorite]
        case .airportAsStop: [.addStop, .call, .favorite, .address]
        case .airportStopOff: [.flyHere, .call, .favorite, .address]
        case .point: [.directTo, .addToRoute, .holdHere]
